/**
 * Post-build script — fixes the wrangler.json generated by @cloudflare/vite-plugin.
 *
 * The plugin generates a fully-expanded wrangler.json in dist/client/ that
 * Cloudflare Pages reads at deploy time. However it includes fields that the
 * version of Wrangler used by Cloudflare Pages rejects:
 *
 *   - "triggers": {}  →  must be omitted or have a "crons" array
 *   - Various unknown top-level and dev fields that cause warnings/errors
 *
 * We strip the bad fields so Cloudflare can read the file cleanly.
 */

import { readFileSync, writeFileSync, existsSync } from "node:fs";
import { join, dirname } from "node:path";
import { fileURLToPath } from "node:url";

const __dirname = dirname(fileURLToPath(import.meta.url));
const file = join(__dirname, "..", "dist", "client", "wrangler.json");

if (!existsSync(file)) {
  console.error("❌ dist/client/wrangler.json not found — build may have failed.");
  process.exit(1);
}

const config = JSON.parse(readFileSync(file, "utf-8"));

// Remove "triggers" if it is empty — Wrangler requires it to have a "crons" array
if (config.triggers !== undefined && Object.keys(config.triggers).length === 0) {
  delete config.triggers;
}

// Remove unknown top-level fields that cause Wrangler parse errors
const unknownTopLevel = [
  "definedEnvironments",
  "ai_search_namespaces",
  "ai_search",
  "secrets_store_secrets",
  "artifacts",
  "unsafe_hello_world",
  "flagship",
  "worker_loaders",
  "ratelimits",
  "vpc_services",
  "vpc_networks",
  "python_modules",
  "legacy_env",
  "userConfigPath",
  "jsx_factory",
  "jsx_fragment",
];
for (const key of unknownTopLevel) {
  delete config[key];
}

// Remove unknown dev sub-fields
if (config.dev) {
  delete config.dev.enable_containers;
  delete config.dev.generate_types;
  // If dev is now empty, remove it entirely
  if (Object.keys(config.dev).length === 0) {
    delete config.dev;
  }
}

writeFileSync(file, JSON.stringify(config, null, 2));
console.log("✅ dist/client/wrangler.json cleaned for Cloudflare Pages deploy.");
